INSERT INTO `reportes` VALUES(1, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Solicitar identificación a todas las personas proveedores y visitantes', 'Solicitar identificación oficial a todo el personal de proveedores y visitantes que ingrese a las instalaciones, para su respectivo registro en la carpeta de bitácora para el control de proveedores y visitantes. A cambio se les proporcionará una credencial y/o tarjetón de visitante PTM para que lo porten en todo momento mientras se encuentren dentro de las instalaciones.', '2022-08-08 12:01:30', 'y', 15, '2022-08-08 12:01:30', 15, '2022-09-11 12:34:56');
