INSERT INTO `reportes` VALUES(15, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'ALCHOLIMETRIA', 'EL GUARDIA DEBERA LLEVAR ACABO LA PRUEBA DE ALCHOLIMETRO A TODO EL PERSONAL QUE INGRE A LAS INSTALACIONES A EXCEPCION DE LOS JEFES AUTORIZADOS, A LOS OPERADORES Y AYUDANTES SE LES DEBERA REALIZAR TAMBIEN CUANDO VALLAN A PROGRAMA,  EN CASO DE DAR POSITIVO REPORTARLO CON EL DEPARTAMENTO DE SEGURIDAD  (SOLO DE LUNES A SABADO Y LOS DOMINGOS DIRECTAMENTE CON EL DEPARTAMENTO DE LOGISTICA).', '2022-08-18 19:00:21', 'y', 5, '2022-08-18 19:00:21', 5, '2022-08-25 16:39:12');
