INSERT INTO `reportes` VALUES(23, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Abrir el portón cuando se requiera el acceso de personal y unidades internos.', 'Se requiere que se habra el porton siempre y cuando sea necesario, cuando no, debera permanecer cerrado.', '2022-08-25 17:06:38', 'y', 5, '2022-08-25 17:06:38', 5, '2022-08-25 16:08:34');
INSERT INTO `reportes` VALUES(24, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', '3.	Verificar que el personal se anote en la lista de asistencia correspondiente.', 'Todos los trabajadores deberan anotarse en las listas de aistencia \r\n\r\nLas listas de alcoholimetria seran entregadas a la ing. Iczamar Avalos \r\nLas listas de asistencia administrativa seran entregadas a la contadora Nathaly', '2022-08-25 17:14:34', 'y', 5, '2022-08-25 17:14:34', 5, '2022-08-25 16:41:10');
INSERT INTO `reportes` VALUES(25, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Verificar que todos los operadores y los ayudantes acceden con overol y botas o zapatos cerrados.', 'Todo el personal operativo debera cumplir con su uniforme correspondiente, en caso de llamarle la atencion y la persona haga caso omiso, favor de reportarlo con el departamento de seguridad ', '2022-08-25 17:16:14', 'y', 5, '2022-08-25 17:16:14', NULL, NULL);
INSERT INTO `reportes` VALUES(26, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Realizar check list de entrada a las unidades de transportes barajas', 'Se deberá realizar el check list de entrada y salida a todas las unidades de transportes barajas. ', '2022-08-25 17:17:44', 'y', 5, '2022-08-25 17:17:44', 5, '2022-08-25 16:28:50');
INSERT INTO `reportes` VALUES(27, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Revisión de unidades externas y maleta de operadores y ayudantes.', 'Se debe realizar la revision al entrar y salir del personal operativo, a si mismo de proeveedores o personal de visita ', '2022-08-25 17:20:14', 'y', 5, '2022-08-25 17:20:14', NULL, NULL);
INSERT INTO `reportes` VALUES(28, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Acceso a personal externo ', 'Cuando un personal externo requiera el acceso; el guardia de seguridad deberá preguntar a qué área se dirige y con qué persona, posterior a ello, se comunicará con la persona indicada para que autorice el acceso. En caso de que la persona a la que se busca no sea ubicada, la persona externa debera contactarla para verificacion de acceso o enterado.', '2022-08-25 17:23:53', 'y', 5, '2022-08-25 17:23:53', NULL, NULL);
INSERT INTO `reportes` VALUES(29, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Instrucciones al personal externo', 'Comunicar al personal externo las instrucciones de entrada a la base, (Lavado de manos, toma de alcoholimetría, registro en bitácoras de personal externo). ', '2022-08-25 17:25:00', 'y', 5, '2022-08-25 17:25:00', NULL, NULL);
INSERT INTO `reportes` VALUES(30, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Limpieza', 'Mantener el área de vigilancia limpia y ordenada.', '2022-08-25 17:29:35', 'y', 5, '2022-08-25 17:29:35', NULL, NULL);
INSERT INTO `reportes` VALUES(31, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Rondines', 'Realizar rondines en los horarios adecuados', '2022-08-25 17:30:20', 'y', 5, '2022-08-25 17:30:20', NULL, NULL);
INSERT INTO `reportes` VALUES(32, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Comunicar al personal indicado', 'Comunicar al personal indicado; anomalías, o incurrencias del personal', '2022-08-25 17:30:56', 'y', 5, '2022-08-25 17:30:56', NULL, NULL);
INSERT INTO `reportes` VALUES(33, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Luces', 'Encender las luces por las noches y apagarlas a las 6 de la mañana (cuando ya se vea claro el dia)', '2022-08-25 17:31:56', 'y', 5, '2022-08-25 17:31:56', NULL, NULL);
INSERT INTO `reportes` VALUES(34, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Borregos y agua', 'Sábados por la tarde, los domingos, dias festivos  y cuando el intendente no se presente a laborar se apoya en el cuidado de los borregos segun la actividad marcada por el intendente, y prender la bomba de agua ', '2022-08-25 17:33:57', 'y', 5, '2022-08-25 17:33:57', 5, '2025-07-23 11:09:11');
INSERT INTO `reportes` VALUES(35, 0, 0, 5, 0, 1, 0, 1, 0, 'c', 'n', 'Llaves de unidades', 'Mantener bajo resguardo las llaves de las unidades, solo se entrega al operador, en todo caso que el ayudante lo requiera el operador tendra que autorizar la entrega.\r\nHabrá ocaciones, que por emergencia logistica tendra el derecho de autorizar a la persona a la que se le dara la llave cuando se requiera ', '2022-08-25 17:38:24', 'y', 5, '2022-08-25 17:38:24', NULL, NULL);
INSERT INTO `reportes` VALUES(36, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Consignas para la seguridad en estacionamientos ', '*El servicio deberá de contar con tres elementos en operación continua sin ninguna excepción uno de 24 horas (8:00) y 2 de 12 horas (10:00).', '2022-09-02 12:45:30', 'y', 4, '2022-09-02 12:45:30', NULL, NULL);
INSERT INTO `reportes` VALUES(37, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Consignas para la seguridad en estacionamientos ', '*Los elementos deberán presentarse a la hora indicada por el encargado del estacionamiento.', '2022-09-02 12:47:04', 'y', 4, '2022-09-02 12:47:04', NULL, NULL);
INSERT INTO `reportes` VALUES(38, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Consignas para la seguridad en estacionamientos ', '*De lunes a domingo el jefe de turno deberá mandar antes de las 10:30 horas su fotografía, que será tomada como asistencia de los elementos, la cual deberá llevar fecha y hora para ser enviada, portando siempre y en todo momento su uniforme completo, el cubre boca, careta o lentes de protección y guantes (de tela o látex).', '2022-09-02 12:57:00', 'y', 4, '2022-09-02 12:57:00', NULL, NULL);
INSERT INTO `reportes` VALUES(39, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Consignas para la seguridad en estacionamientos ', '*El elemento de 24 horas no podrá retirarse del punto de emisoras antes de ser relavado por su compañero, deberá estar pendiente, desde el momento que se abre el estacionamiento, para evitar que los usuarios o personal de la tienda ingresen sin boletos.', '2022-09-02 12:59:40', 'y', 4, '2022-09-02 12:59:40', NULL, NULL);
INSERT INTO `reportes` VALUES(40, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Consignas para la seguridad en estacionamientos ', '*(Persona que se reporte en oficina que no había guardia para auxiliarlo, se les hará el cobrar de boleto perdido al elemento en turno).', '2022-09-02 13:01:37', 'y', 4, '2022-09-02 13:01:37', NULL, NULL);
INSERT INTO `reportes` VALUES(41, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Apertura de cierre de caseta', '*Cada caseta cuenta con una chapa nueva la cual se deberá abrir solo con la llave, si algún guardia o cajero es reportado abriendo con otro objeto se le cobrar el daño.', '2022-09-02 13:04:09', 'y', 4, '2022-09-02 13:04:09', NULL, NULL);
INSERT INTO `reportes` VALUES(42, 0, 0, 4, 0, 18, 0, 8, 0, 'c', 'n', 'Apertura de cierre de caseta', '*En la salida de 14:00 horas y 15:00 horas se deberá apoyar a tienda bajando las cortinas 10 minutos antes de las 23:00 horas.', '2022-09-02 13:08:51', 'y', 4, '2022-09-02 13:08:51', NULL, NULL);
INSERT INTO `reportes` VALUES(43, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Prohibido salirse de las instalaciones PTM durante su guardia.', 'Queda estrictamente prohibido salirse de las instalaciones PTM en sus guardias, salvo alguna excepción notificada y aprobada por el proveedor (SETEINC) y Cliente (Petrotab). ', '2022-09-11 13:23:15', 'y', 15, '2022-09-11 13:23:15', NULL, NULL);
INSERT INTO `reportes` VALUES(44, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Realización de antidopaje al guardia en turno.', 'Realización de antidopaje una vez al mes al guardia en turno seleccionado al azar, en presencia de personal de PTM.', '2022-09-11 13:24:08', 'y', 15, '2022-09-11 13:24:08', NULL, NULL);
INSERT INTO `reportes` VALUES(45, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Únicamente permitir acceso a proveedores y visitantes con Equipo de Protección Personal y/o ropa y zapatos de trabajo.', 'Revisar previo al ingreso a las instalaciones PTM, que todo proveedor y visitantes porte equipo de protección personal (EPP) y/o ropa y zapatos de trabajo de acuerdo con las actividades que realizará dentro de las instalaciones, de lo contrario no se permitirá el acceso. Salvo algún caso de excepción.', '2022-09-11 13:26:52', 'y', 15, '2022-09-11 13:26:52', NULL, NULL);
INSERT INTO `reportes` VALUES(46, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Revisar de manera visual mochilas, bolsos, etc. a proveedores y visitantes que ingresen a las instalaciones PTM.', 'Revisar de manera visual mochilas, cajas, contenedores, etc. a todas las personas de proveedores y visitantes que ingresen a nuestras instalaciones.\r\nEl proveedor y/o visitante, al ingresar a las instalaciones PTM deberán llevar una lista de sus herramientas y equipos, se les verificará a la salida la cual deberá coincidir con las herramientas y equipo ingresado a las instalaciones. De lo contrario deberá contar con pase de salida autorizado de la herramienta y equipo. \r\n', '2022-09-11 13:28:10', 'n', 15, '2022-09-11 13:28:10', 393, '2024-05-22 12:09:34');
INSERT INTO `reportes` VALUES(47, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Dar indicaciones a proveedores y visitantes sobre las áreas de estacionamiento dentro y fuera de las instalaciones PTM.', 'Dar indicaciones a proveedores y visitantes sobre las áreas de estacionamiento asignadas dentro y fuera de las instalaciones PTM para vehículos ligeros, vehículos pesados, motocicletas, incluidas en el listado autorizado.\r\n-	Estacionarse en los lugares asignados.\r\n', '2022-09-11 13:30:02', 'y', 15, '2022-09-11 13:30:02', NULL, NULL);
INSERT INTO `reportes` VALUES(48, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Dar indicaciones a proveedores y visitantes sobre las áreas de acceso peatonal designadas de las instalaciones PTM.', 'Dar indicaciones a proveedores y visitantes sobre las áreas de acceso peatonal designadas de las instalaciones Petrotab, es decir por donde debe caminar para dirigirse al área de oficinas, comedor, almacén, etc. deberán transitar por el área peatonal delimitada en color verde y/o amarilla. Para acceder a las áreas operativas como el taller de mantenimiento, área de geomembranas, patio de maniobras, deberán portar ropa de trabajo, zapatos de trabajo y casco de seguridad, siempre acompañado de personal PTM responsable y/o a cargo de la actividad que vaya a desempeñar el proveedor o visitante.', '2022-09-11 13:30:59', 'y', 15, '2022-09-11 13:30:59', NULL, NULL);
INSERT INTO `reportes` VALUES(49, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Proporcionar EPP para visitantes en caso de ser necesario (Casco, punteras, etc.).', 'Proporcionar cascos y punteras de seguridad al personal visitante que se dirija a las áreas operativas (En caso de que la visita no tenga). PTM deberá proporcionar dicho equipo (casco y punteras) en calidad de préstamo y el personal de vigilancia deberá llevar un control y será su responsabilidad tenerlo en resguardo. ', '2022-09-11 13:32:24', 'y', 15, '2022-09-11 13:32:24', NULL, NULL);
INSERT INTO `reportes` VALUES(50, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Usar codificación de nombres en teléfonos celular ', 'Usar codificación de nombres en teléfonos celular, Ptm les proporciona un listado actualizado del personal con código de números y letras asignados a cada persona, cada vez que se realice una actualización del personal, y deberán reportar con el mismo formato, sin omisiones, etc.', '2022-09-11 13:33:46', 'n', 15, '2022-09-11 13:33:46', 393, '2024-05-22 12:05:36');
INSERT INTO `reportes` VALUES(51, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Realizar prueba de alcoholemia a toda persona que ingrese a las instalaciones PTM sin excepción.', 'Realizar prueba de alcoholemia a toda persona, ya sea colaborador, visitante o proveedor sin excepción, que ingrese a las instalaciones PTM por acceso peatonal, en vehículo corporativo o vehículo personal.\r\nNota: El equipo (alcoholímetro) será proporcionado por proveedor SETEINC.\r\n', '2022-09-11 13:36:10', 'y', 15, '2022-09-11 13:36:10', NULL, NULL);
INSERT INTO `reportes` VALUES(52, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Solicitar identificación corporativa a personal PTM al ingresar a las instalaciones.', 'Solicitar y verificar a diario que todo el personal PTM deberá mostrar su identificación corporativa al ingresar a las instalaciones de manera diaria, a excepción de personal de nuevo ingreso el cual deberá mostrar su identificación oficial al ingresar durante los siguientes 7 días como máximo.', '2022-09-11 13:36:46', 'y', 15, '2022-09-11 13:36:46', NULL, NULL);
INSERT INTO `reportes` VALUES(53, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Registro de asistencia entrada y salida.', 'Personal de vigilancia deberá colocar registro de horario (entrada y salida) de los colaboradores PTM, esta última solo colocará la firma de manera diaria al ingresar a las instalaciones.', '2022-09-11 13:37:45', 'y', 15, '2022-09-11 13:37:45', NULL, NULL);
INSERT INTO `reportes` VALUES(54, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Acceso vehicular de colaboradores PTM a las instalaciones con tarjetón de acceso.', 'Personal de vigilancia deberá solicitar tarjetón de acceso (Marbete) a los colaboradores que tengan autorizado ingresar su vehículo personal. Cada vez que se realice actualización de los vehículos personales de los colaboradores PTM, les será proporcionado.', '2022-09-11 13:38:24', 'y', 15, '2022-09-11 13:38:24', NULL, NULL);
INSERT INTO `reportes` VALUES(55, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Restricción de acceso a colaboradores que lleguen fuera de horario permitido.', 'Se restringirá acceso a los colaborares que lleguen después de los 10 minutos de tolerancia sin previa autorización de su supervisor directo.\r\nÚnicamente se les permitirá el acceso si cuentan con permiso/autorización de su supervisor directo y/o el departamento RH.\r\nPersonal PTM (Coordinadores) deberá notificar a personal de vigilancia que el colaborador llegará fuera de horario permitido.\r\n', '2022-09-11 13:39:54', 'y', 15, '2022-09-11 13:39:54', NULL, NULL);
INSERT INTO `reportes` VALUES(56, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Revisión a personal y unidades PTM', 'Revisión visual de las mochilas diario en la entrada y salida de los de nuestros colaboradores también, así como las unidades PTM, reportar cualquier anomalía. \r\nPersonal PTM deberá notificar a personal de vigilancia si lleva equipo de cómputo, para que quede registro en bitácora.', '2022-09-11 13:41:03', 'y', 15, '2022-09-11 13:41:03', NULL, NULL);
INSERT INTO `reportes` VALUES(57, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Reportar ingreso del primer y último colaborador a las instalaciones PTM.', 'Reportar ingreso del primer y último colaborador de las instalaciones PTM, en el grupo whatsapp o en la APP con nombre y hora.\r\nAsí como si el personal vuelve a ingresar por cuestiones operativas.\r\n', '2022-09-11 13:42:35', 'y', 15, '2022-09-11 13:42:35', NULL, NULL);
INSERT INTO `reportes` VALUES(58, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Únicamente se permitirá acceso a las instalaciones PTM a visitantes y proveedores registrados / aprobados.', 'Únicamente se permitirá acceso a las instalaciones PTM a visitantes y proveedores registrados / aprobados con anticipación, o algún caso de excepción.\r\nLas notificaciones deberán contar con los siguientes datos:\r\nProveedor / Compañía:\r\nNombres:\r\nFecha:\r\nHora aproximada:\r\nTipo de servicio:\r\nAtiende en PTM:\r\nColaborador de PTM deberá acompañar en todo momento a su visitante o designar a personal para que lo haga, en especial si realizará alguna actividad critica en el área de operaciones.', '2022-09-11 13:43:18', 'y', 15, '2022-09-11 13:43:18', NULL, NULL);
INSERT INTO `reportes` VALUES(59, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Realizar protocolo sanitario de acceso a las instalaciones en acceso peatonal y/o en unidades PTM o particulares.', 'Realizar protocolo sanitario de acceso a las instalaciones en acceso peatonal y/o en unidades PTM o particulares a toda persona que ingrese a las instalaciones..', '2022-09-11 13:44:11', 'n', 15, '2022-09-11 13:44:11', 393, '2024-05-22 11:59:57');
INSERT INTO `reportes` VALUES(60, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Horario de atención a visitantes y proveedores en las instalaciones PTM.', 'Solo se atenderá a visitantes y proveedores en horario 08:30 a 15:00 horas de lunes a viernes, sábados 08:30 a 12:00, salvo alguna excepción.\r\nEl usuario PTM se hará responsable de la supervisión de este, durante su estadía dentro e las instalaciones.', '2022-09-11 13:45:39', 'y', 15, '2022-09-11 13:45:39', NULL, NULL);
INSERT INTO `reportes` VALUES(61, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'No podrá abrir la puerta a nadie sino está previamente autorizado.', 'No podrá recibir, ni abrir la puerta a nadie que no esté autorizado, y que no llegue en horarios establecidos. Tampoco se recibirá material o servicios fuera de horario, sin previo aviso de personal PTM.', '2022-09-11 13:46:20', 'y', 15, '2022-09-11 13:46:20', NULL, NULL);
INSERT INTO `reportes` VALUES(62, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Reportar situaciones diferentes a lo habitual y resguardar las pertenencias, artículos, herramientas y equipos.', 'Durante los recorridos / rondines en las instalaciones PTM, si encuentran algo diferente a lo habitual deberá reportarlo en la APP SETEINC, en el grupo de WhatsApp y registrarlo en bitácora. Si encuentran algo deberán resguardar lo que se encuentren para entregarlas al día siguiente a personal PTM.', '2022-09-11 13:47:21', 'y', 15, '2022-09-11 13:47:21', NULL, NULL);
INSERT INTO `reportes` VALUES(63, 0, 0, 2, 0, 17, 0, 9, 0, 'r', 'n', 'Criztalazos', '', '2022-09-19 06:09:15', 'y', 2, '2022-09-19 06:09:15', NULL, NULL);
INSERT INTO `reportes` VALUES(64, 0, 0, 6, 1, 1, 0, 1, 0, 'b', 'n', '19/09/2022', 'Inicio de bitacora', '2022-09-19 16:20:26', 'y', 6, '2022-09-19 16:20:26', NULL, NULL);
INSERT INTO `reportes` VALUES(65, 0, 0, 15, 0, 7, 0, 4, 0, 'c', 'n', 'Abrir ambas puertas del portón, para acceso de vehículos pesados', 'Cuando salgan o ingresen los vehículos pesados con o sin equipos (Frak Tanq), se deberán abrir ambas puertas del portón para facilitar las maniobras de acceso a las instalaciones PTM.', '2022-09-20 13:15:15', 'y', 15, '2022-09-20 13:15:15', NULL, NULL);
INSERT INTO `reportes` VALUES(66, 4, 41, 93, 27, 20, 0, 19, 0, 'b', 'n', '21/09/2022', 'Inicio de Turno Guardia Angel Yahir Lopez Contreras ', '2022-09-21 13:17:06', 'y', 93, '2022-09-21 13:17:06', NULL, NULL);
INSERT INTO `reportes` VALUES(67, 0, 0, 36, 0, 12, 0, 11, 0, 'b', 'n', '21/09/2022', '', '2022-09-21 17:12:01', 'y', 36, '2022-09-21 17:12:01', NULL, NULL);
INSERT INTO `reportes` VALUES(68, 0, 0, 36, 0, 12, 0, 11, 0, 'c', 'n', 'VELAR POR EL CUMPLIMIENTO DE  EL PROTOCOLO DE LIMPIEZA Y CONVIVENCIA EN LOS DORMITORIOS ', 'Supervisar y tratar que los huéspedes cumplan con la siguiente cultura de convivencia en los dormitorios.\r\n1.	No usar barandales para colgar objetos o ropa.\r\n2.	Tirar la basura en los contenedores asignados para su uso.\r\n3.	No fumar en área de dormitorios.\r\n4.	No ingerir bebidas alcohólicas dentro de los dormitorios o en el área de los baños.\r\n5.	Respetar el área asignada para fumadores.\r\n6.	No mover mobiliario de la plaza como sillas y mesas a otras áreas sin previa autorización.\r\n7.	No rayas paredes o puertas.\r\n8.	Bajarle la palanca a los W.C. o mingitorios cada vez que sean usados.\r\n9.	Respetar el tiempo de uso de la regadera de 5 minutos.\r\n10.	Respetar las camas asignadas y los lugares de los demás.\r\n11.	No usar camas vacías como mesas o para colocar ropa u otras pertenencias.\r\n12.	Cerrar las puertas de los dormitorios cuando el mini Split este encendido.\r\n13.	Colocar de forma ordenada sus pertenencias, para evitar obstruir los pasillos.\r\n14.	No almacenar basura en los pasillos de los dormitorios o camas.\r\n\r\n', '2022-09-21 17:35:19', 'y', 36, '2022-09-21 17:35:19', 36, '2022-09-26 08:15:08');
INSERT INTO `reportes` VALUES(69, 0, 0, 36, 0, 12, 0, 11, 0, 'c', 'n', 'CORROBORAR EL NUMERO DE CAMAS OCUPADAS', 'Cotejo de la información dada por el encargado acerca del número de camas ocupadas, con la cantidad de personas instaladas mediante una lista dada todos los días por el administrador a excepción de los domingos.\r\nEn caso de que haya una persona ajena a la lista dada, comunicarse con el administrador para determinar que acción tomar.\r\nAnotar en la lista las entradas y salidas de los huéspedes.', '2022-09-21 17:45:50', 'y', 36, '2022-09-21 17:45:50', 36, '2022-10-01 13:23:26');
INSERT INTO `reportes` VALUES(70, 0, 0, 36, 0, 12, 0, 11, 0, 'c', 'n', 'RENTA DE CAMAS ', 'En caso de que llegue una persona solicitando dormitorio primero avisar con el administrador para checar la disponibilidad.\r\nTomar en cuenta si la persona que solicita hospedaje no esta en estado de ebriedad.\r\nSolicitar los datos de las persona que se va a ingresar nombre, numero de celular y anotar numero de cama y dormitorio.\r\nEn caso de no tomar en cuenta lo anterior y la persona que se ingresa sin conocimiento del administrador ocasiona daños a terceros o a la plaza estos serán remediados por la empresa de seguridad.\r\nCobrar de acuerdo a la tarifa establecida por la plaza de $115 pesos por persona por cama.\r\n', '2022-09-21 17:53:02', 'y', 36, '2022-09-21 17:53:02', NULL, NULL);
INSERT INTO `reportes` VALUES(71, 0, 0, 36, 0, 12, 0, 11, 0, 'c', 'n', 'ASEGURAR EL ACTIVO FIJO DE LOS DORMITORIOS', 'Llevar un conteo diario del numero de almohadas en los dormitorios.\r\nPasar lista de huéspedes a las 7:30 pm para checar que no haya persona ajena y en caso de haberla reportar con el administrador.\r\nRealizar recorrido en el dormitorio a las 10:30 pm para checar que no haya persona ajena en los dormitorios.\r\nRealizar recorridos cada 3 horas en el área de los baños para asegurar el orden, checar que no sea obstruida o movida la cámara y checar que no se este tirando el agua en los W.C., lavabos o regaderas.\r\nLlenar la lista del control de entradas y salidas de los huéspedes, para así tener la certeza de las personas que se encuentran en los dormitorios.\r\nEstar atento al área de entrada del dormitorio para asegurar que los huéspedes cuando se vayan no se lleven algún activo como sabanas, almohadas, etc. \r\nApagar el aire acondicionado a la hora que se retire el ultimo huésped en la mañana y cerrar la puerta con candado o solo el pasador, en caso de que quede una persona reportar al administrador para revisar la acción a tomar.', '2022-09-21 18:04:11', 'y', 36, '2022-09-21 18:04:11', 36, '2022-09-26 08:13:45');
INSERT INTO `reportes` VALUES(72, 5, 40, 92, 27, 20, 0, 19, 0, 'b', 'n', '22/09/2022', 'Buenos días realiza cambio de guardia en el servicio JL logística', '2022-09-22 07:53:31', 'y', 92, '2022-09-22 07:53:31', NULL, NULL);
