INSERT INTO `reportesrecurrentes` VALUES(3, 15, 4, 'Alcoholimia positivo', 'En caso de que una colaborador de Petrotab, resulte positivo durante la verificación de alcoholimia al ingresar a las instalaciones deberá notificarlo al coordinador de QHSE (Mónica Carmona, Celular 938 125 4897) y este le dará seguimiento con su RH y sup', 'y', 15, '2022-08-08 12:09:58', NULL, NULL);
