INSERT INTO `reportesrecurrentes` VALUES(8, 36, 11, 'REPORTAR EL CIERRE DEL BAR', 'Reportar la hora de cierre del bar y colocar fotografía.', 'y', 36, '2022-10-01 14:21:52', NULL, NULL);
INSERT INTO `reportesrecurrentes` VALUES(9, 36, 11, 'REPORTAR CUANDO SE OCUPE UNA CAMA', 'Reportar cuando se venda una cama y el nombre del huésped. La tarifa es de 115', 'y', 36, '2022-10-01 15:46:13', NULL, NULL);
